import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.mzJ8I8R4.js";const k=JSON.parse('{"title":"部署服务器","description":"","frontmatter":{},"headers":[],"relativePath":"guide/server.md","filePath":"guide/server.md"}'),n={name:"guide/server.md"};function d(o,s,p,l,h,r){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="部署服务器" tabindex="-1">部署服务器 <a class="header-anchor" href="#部署服务器" aria-label="Permalink to &quot;部署服务器&quot;">​</a></h1><p>要在多台设备之间同步，或者在浏览器里使用网页版，需要一台自己的服务器。服务端和网页版打包在同一个 Docker 镜像里，部署一次，网页、Android、macOS 和 Windows 都能连上。</p><p>只在一台设备上用的，不需要服务器，见<a href="./local">在本机使用</a>。</p><h2 id="需要准备" tabindex="-1">需要准备 <a class="header-anchor" href="#需要准备" aria-label="Permalink to &quot;需要准备&quot;">​</a></h2><ul><li><strong>一台 Linux 服务器</strong>：云服务器（VPS）、家里的 NAS 或小主机都可以，amd64 或 arm64。NextTodo 占用很少，配置要求不高。</li><li><strong>Docker</strong>：按 <a href="https://docs.docker.com/engine/install/" target="_blank" rel="noreferrer">Docker 官方文档</a>安装 Docker Engine，它自带 Docker Compose。NAS 的系统里一般叫 Container Manager 或“容器”。</li><li><strong>受信任的 HTTPS 证书</strong>：Android App 和网页版只能通过 HTTPS 连接服务器，证书要是手机和浏览器默认信任的，比如 Let&#39;s Encrypt 签发的；自己签发的证书手机不认，所以没有受信任证书的地址都连不上。证书一般给域名申请： <ul><li>服务器在公网上：在域名服务商那里添加一条 A 记录，把域名（比如 <code>todo.example.com</code>）指向服务器的公网 IP。在中国大陆的服务器上用域名提供网站，需要先完成备案。</li><li>没有域名，或者域名暂时用不了（比如还在备案）：可以直接用服务器的公网 IP，Let&#39;s Encrypt 也给公网 IP 签证书，见<a href="#ip">只用 IP 地址</a>。</li><li>只在家里的局域网里用：同样需要一个域名和受信任的证书，比如用 DNS 验证的方式申请证书，再在路由器或局域网 DNS 里把域名指向这台机器。</li></ul></li><li><strong>一个反向代理</strong>：负责 HTTPS，把请求转给 NextTodo。Caddy、Nginx、OpenResty、1Panel 或宝塔面板里的网站、NAS 自带的反向代理都可以，服务器上已经有的就直接用它，要求见<a href="#proxy">第 2 步</a>。</li><li><strong>放行端口</strong>：在防火墙（云服务器还有安全组）里放行反向代理用的端口，通常是 443；用 HTTP 验证的方式自动申请证书（Caddy 默认就是）还要放行 80。</li></ul><p>下面的命令都在服务器的终端里运行（用 SSH 登录服务器）。</p><h2 id="start" tabindex="-1">1. 启动 NextTodo <a class="header-anchor" href="#start" aria-label="Permalink to &quot;1. 启动 NextTodo {#start}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSLO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/JunieXD/NextTodo/main/deploy/compose.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 65534:65534</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>这几行依次：建一个目录，下载配置文件，建好存放数据的 <code>data</code> 目录（NextTodo 在容器里以 65534 号用户运行，目录要归它），启动 NextTodo。数据库和每日快照都在 <code>data</code> 里。</p><p>检查它是否在运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/v1/me</span></span></code></pre></div><p>返回 <code>{&quot;code&quot;:&quot;unauthenticated&quot;,&quot;message&quot;:&quot;请先登录&quot;}</code> 就说明 NextTodo 已经启动，只是还没登录。</p><p>NextTodo 默认只在这台机器内部的 <code>127.0.0.1:8080</code> 上运行，外面访问不到，由同一台机器上的反向代理转给它：</p><ul><li><strong>换端口</strong>：8080 被占用时，在 <code>nexttodo</code> 目录里建一个 <code>.env</code> 文件，写上 <code>NEXTTODO_PORT=8790</code>，再运行 <code>docker compose up -d</code>。下面的 8080 都换成新端口。</li><li><strong>反向代理连不到 <code>127.0.0.1</code></strong>：反向代理在另一台机器上，或者它自己也跑在 Docker 容器里（且不是 host 网络）时，它那边的 <code>127.0.0.1</code> 指的不是这台机器。这时把 <code>compose.yaml</code> 里 <code>ports</code> 一行开头的 <code>127.0.0.1</code> 换成反向代理能访问到的地址（比如这台机器的局域网 IP），再运行 <code>docker compose up -d</code>。这个端口是不加密的 HTTP，不要对公网开放。</li></ul><h2 id="proxy" tabindex="-1">2. 配置反向代理和 HTTPS <a class="header-anchor" href="#proxy" aria-label="Permalink to &quot;2. 配置反向代理和 HTTPS {#proxy}&quot;">​</a></h2><p>不管用哪个反向代理，NextTodo 只要求这几点：</p><table tabindex="0"><thead><tr><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>用 HTTPS 提供，证书受信任</td><td>浏览器打开 <code>https://你的域名</code>（或 IP）时，地址栏没有证书警告</td></tr><tr><td>整个网站转发到 <code>http://127.0.0.1:8080</code></td><td>要单独占一个域名、子域名或 IP，不能放在某个路径下（如 <code>example.com/todo</code>）</td></tr><tr><td>支持 WebSocket</td><td>各设备靠 <code>/api/v1/sync</code> 上的 WebSocket 实时同步。NextTodo 每 30 秒发一次心跳，反向代理的空闲超时不能短于 30 秒（Nginx 默认的 60 秒就够）</td></tr><tr><td>把原来的 <code>Host</code> 传过去</td><td>或者设置 <code>X-Forwarded-Host</code>。网页版的同步连接靠它确认是同一个网站</td></tr></tbody></table><p>下面是常见的几种写法，域名都换成自己的。</p><h3 id="caddy" tabindex="-1">Caddy <a class="header-anchor" href="#caddy" aria-label="Permalink to &quot;Caddy&quot;">​</a></h3><p>Caddy 会自动申请和续期证书，上面的要求默认都满足。按 <a href="https://caddyserver.com/docs/install" target="_blank" rel="noreferrer">Caddy 官方文档</a>安装后，在 <code>/etc/caddy/Caddyfile</code> 里加上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>todo.example.com {</span></span>
<span class="line"><span>	reverse_proxy 127.0.0.1:8080</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行 <code>sudo systemctl reload caddy</code> 让配置生效。</p><h3 id="nginx-或-openresty" tabindex="-1">Nginx 或 OpenResty <a class="header-anchor" href="#nginx-或-openresty" aria-label="Permalink to &quot;Nginx 或 OpenResty&quot;">​</a></h3><p>OpenResty 基于 Nginx，写法相同。证书用 certbot 等工具申请，或者用已有的：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">todo.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    /path/to/fullchain.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/privkey.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>proxy_set_header Host</code> 传原来的 <code>Host</code>，后三行开启 WebSocket。改完运行 <code>sudo nginx -s reload</code>（OpenResty 是 <code>sudo openresty -s reload</code>）。</p><h3 id="面板和-nas-自带的反向代理" tabindex="-1">面板和 NAS 自带的反向代理 <a class="header-anchor" href="#面板和-nas-自带的反向代理" aria-label="Permalink to &quot;面板和 NAS 自带的反向代理&quot;">​</a></h3><p>1Panel、宝塔、群晖这类面板通常有“反向代理”或“网站”功能。新建一个，按上面的表格填写：目标（后端）地址填 <code>http://127.0.0.1:8080</code>，打开 WebSocket 支持，申请或上传证书。有的面板没有 WebSocket 开关，要在自定义配置里加上和上面 Nginx 一样的 <code>Upgrade</code>、<code>Connection</code> 两行。具体在哪里设置，见面板自己的文档。</p><h3 id="ip" tabindex="-1">只用 IP 地址 <a class="header-anchor" href="#ip" aria-label="Permalink to &quot;只用 IP 地址 {#ip}&quot;">​</a></h3><p>没有能用的域名时，可以给服务器的公网 IP 申请 Let&#39;s Encrypt 的证书。这种证书的有效期只有 6 天左右，要靠程序自动续期，用 Caddy（2.11 或更新的版本）最省事。Caddyfile 写成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>	default_sni 203.0.113.10</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>203.0.113.10 {</span></span>
<span class="line"><span>	tls {</span></span>
<span class="line"><span>		issuer acme {</span></span>
<span class="line"><span>			profile shortlived</span></span>
<span class="line"><span>		}</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>	reverse_proxy 127.0.0.1:8080</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>两处 <code>203.0.113.10</code> 都换成服务器的公网 IP。只能用公网 IP，<code>192.168.x.x</code> 这类局域网地址申请不到；公网 IP 变了要改配置。</li><li><code>profile shortlived</code> 申请 IP 证书要用的短期证书。Caddy 在到期前自己续期，保持它一直运行就行。</li><li><code>default_sni</code> 不能省：按 IP 访问时，App 和浏览器不告诉服务器要访问哪个名字，云服务器上 Caddy 看到的本机地址又往往是内网 IP，没有这一行它就不知道该用哪张证书，证书申请下来了，连接照样失败。</li><li>Let&#39;s Encrypt 验证时要从外网按 IP 连到服务器的 80 或 443 端口，防火墙和安全组要放行这两个端口。</li><li>App 里的服务器地址填这个 IP，比如 <code>203.0.113.10</code>。</li></ul><p>也可以用别的工具申请，前提是它支持 Let&#39;s Encrypt 的 <code>shortlived</code> 证书档，能每隔几天自动续期，续期后让反向代理加载新证书，比如 certbot 5.3 起的 <code>--ip-address</code>。</p><h3 id="检查" tabindex="-1">检查 <a class="header-anchor" href="#检查" aria-label="Permalink to &quot;检查&quot;">​</a></h3><p>用浏览器打开 <code>https://todo.example.com</code>（只用 IP 的打开 <code>https://</code> 加 IP），能看到 NextTodo 的登录页、地址栏没有证书警告，就成功了。WebSocket 是否正常，要在下一步登录以后才看得出来，见<a href="#troubleshooting">遇到问题</a>。</p><h2 id="_3-创建账号并登录" tabindex="-1">3. 创建账号并登录 <a class="header-anchor" href="#_3-创建账号并登录" aria-label="Permalink to &quot;3. 创建账号并登录&quot;">​</a></h2><p>回到 <code>nexttodo</code> 目录，创建管理员账号。下面的 <code>admin</code> 是用户名，可以换成自己想用的（字母、数字和下划线），然后按提示输入两次密码：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /nexttodo-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span></span></code></pre></div><p>然后在 App 里点“连接服务器”，服务器地址填域名（如 <code>todo.example.com</code>）或 IP，再填用户名和密码登录。浏览器里打开这个地址就是网页版。</p><p>谁忘了密码（包括管理员自己），在 <code>nexttodo</code> 目录里运行下面的命令，把 <code>admin</code> 换成那个人的用户名，再按提示输入两次新密码。这个账号的设备都要用新密码重新登录，API 令牌不受影响。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /nexttodo-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span></span></code></pre></div><p>提示认不出 <code>reset-password</code> 时，说明镜像还是旧的（在设置里升级过），先按<a href="#用命令升级">用命令升级</a>拉取新镜像。</p><h2 id="_4-邀请其他人" tabindex="-1">4. 邀请其他人 <a class="header-anchor" href="#_4-邀请其他人" aria-label="Permalink to &quot;4. 邀请其他人&quot;">​</a></h2><p>每人一个账号，数据彼此独立。管理员在“设置 → 邀请注册”里点“生成邀请码”，邀请链接会自动复制，发给对方即可。对方打开链接，或者在登录页选“邀请码注册”并填入邀请码，就能注册。每个邀请码只能注册一个账号。</p><h2 id="ai" tabindex="-1">5. 让服务器替你整理 <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;5. 让服务器替你整理 {#ai}&quot;">​</a></h2><p><a href="./ai">AI 整理</a>的配置默认只能保存在各自的设备上，整理时设备要联网。想让服务器自己整理、提交后设备可以离线，要给服务器设一个加密密钥：</p><ol><li><p>在 <code>nexttodo</code> 目录里运行下面的命令，生成密钥并写进 <code>.env</code> 文件：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;NEXTTODO_SECRET_KEY=$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div></li><li><p>运行 <code>docker compose up -d</code> 让它生效。</p></li><li><p>在 App 的“设置 → AI 整理”里，保存位置选“同步到服务器”。</p></li></ol><p>服务器用这个密钥加密保存大家的 API 密钥。<code>.env</code> 文件要保管好；换掉或丢了它，已保存的 API 密钥就解不开，要重新填写。</p><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><p>出了新版本时，管理员打开 NextTodo 会看到提示条“服务器可升级到 0.1.N”，“设置 → 关于”里也写着。想第一时间知道，可以在 <a href="https://github.com/JunieXD/NextTodo" target="_blank" rel="noreferrer">GitHub 仓库</a>右上角点 <strong>Watch</strong> → <strong>Custom</strong>，勾选 <strong>Releases</strong> 后点 <strong>Apply</strong>，发布新版本时 GitHub 会发邮件通知。</p><p>升级有两种方法，结果一样，可以混用。数据会自动升级，不用另外操作。App 不用手动升级：服务器升级后，各设备的 App 会自动获取新版本。</p><h3 id="在设置里升级" tabindex="-1">在设置里升级 <a class="header-anchor" href="#在设置里升级" aria-label="Permalink to &quot;在设置里升级&quot;">​</a></h3><p>在“设置 → 关于”的“服务器版本”一行点 <strong>升级</strong>，确认后，服务器自己下载新版本并换上，这一行显示下载的进度。换上时各设备会断开几秒，随后自动重连，网页会自动刷新。新版本起不来时，服务器自动退回原来的版本，数据不受影响。</p><ul><li>服务器要能连上 GHCR（<code>ghcr.io</code>），连不上时用命令升级。</li><li>这一行没有 <strong>升级</strong> 按钮的，是服务器的版本太旧：用命令升级一次，以后就能在设置里升级了。</li><li>在 <code>.env</code> 里用 <code>NEXTTODO_IMAGE</code> 固定了版本的，在设置里升级以后，服务器用的是新版本。要换回旧版本，见<a href="https://github.com/JunieXD/NextTodo/blob/main/docs/deploy.md#%E5%9C%A8%E8%AE%BE%E7%BD%AE%E9%87%8C%E5%8D%87%E7%BA%A7" target="_blank" rel="noreferrer">部署文档</a>。</li></ul><h3 id="用命令升级" tabindex="-1">用命令升级 <a class="header-anchor" href="#用命令升级" aria-label="Permalink to &quot;用命令升级&quot;">​</a></h3><p>在服务器上的 <code>nexttodo</code> 目录里运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>如果在 <code>.env</code> 里写了 <code>NEXTTODO_IMAGE</code> 固定版本，先把其中的版本号改成新的。</p><h2 id="备份" tabindex="-1">备份 <a class="header-anchor" href="#备份" aria-label="Permalink to &quot;备份&quot;">​</a></h2><p>服务器每天在 <code>data/snapshots/</code> 里保存一份数据库快照，保留最近 7 份。把这些快照定期复制到别处，就是备份。从快照恢复的步骤见<a href="https://github.com/JunieXD/NextTodo/blob/main/docs/deploy.md#%E5%A4%87%E4%BB%BD%E5%92%8C%E6%81%A2%E5%A4%8D" target="_blank" rel="noreferrer">部署文档</a>。</p><h2 id="troubleshooting" tabindex="-1">遇到问题 <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;遇到问题 {#troubleshooting}&quot;">​</a></h2><p>先看 NextTodo 的日志：在 <code>nexttodo</code> 目录里运行 <code>docker compose logs --tail 100</code>。</p><table tabindex="0"><thead><tr><th>现象</th><th>多半是</th><th>检查</th></tr></thead><tbody><tr><td>网页打不开</td><td>域名、端口或反向代理</td><td>域名是否指向这台服务器，端口是否放行，反向代理是否在运行，它的错误日志</td></tr><tr><td>502 Bad Gateway</td><td>反向代理连不到 NextTodo</td><td>NextTodo 是否在运行（<a href="#start">第 1 步</a>的 <code>curl</code>），反向代理转发的地址和端口对不对；反向代理在容器里时见第 1 步最后一条</td></tr><tr><td>浏览器提示证书不安全，App 连接失败</td><td>证书不受信任或过期</td><td>换成受信任的证书，比如 Let&#39;s Encrypt；只能用 IP 访问的见<a href="#ip">只用 IP 地址</a></td></tr><tr><td>只用 IP，证书申请下来了，但浏览器和 App 都连不上</td><td>没设 <code>default_sni</code></td><td>见<a href="#ip">只用 IP 地址</a></td></tr><tr><td>能登录，但一直显示“离线”，别的设备的改动要刷新才出现</td><td>WebSocket 没打通</td><td>反向代理是否开了 WebSocket；网页版还要检查是否传了原来的 <code>Host</code></td></tr><tr><td>App 里填服务器地址后连接失败，浏览器能打开</td><td>地址写错</td><td>只填域名（如 <code>todo.example.com</code>）或 IP，不写路径；不写协议时按 <code>https://</code></td></tr></tbody></table>`,63)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
